#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\xampp\htdocs\tabler-dev\node_modules\.pnpm\imageoptim-cli@3.1.9\node_modules\imageoptim-cli\node_modules;C:\xampp\htdocs\tabler-dev\node_modules\.pnpm\imageoptim-cli@3.1.9\node_modules;C:\xampp\htdocs\tabler-dev\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/xampp/htdocs/tabler-dev/node_modules/.pnpm/imageoptim-cli@3.1.9/node_modules/imageoptim-cli/node_modules:/mnt/c/xampp/htdocs/tabler-dev/node_modules/.pnpm/imageoptim-cli@3.1.9/node_modules:/mnt/c/xampp/htdocs/tabler-dev/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

# Support pipeline input
if ($MyInvocation.ExpectingInput) {
  $input | & "$basedir/../imageoptim-cli/dist/imageoptim"   $args
} else {
  & "$basedir/../imageoptim-cli/dist/imageoptim"   $args
}
$env:NODE_PATH=$env_node_path
exit $LASTEXITCODE
